BEGIN;
CREATE TABLE IF NOT EXISTS roles (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE CHECK(name IN ('admin','user')),description TEXT);
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,role_id BIGINT NOT NULL REFERENCES roles(id),full_name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS monitoring_sites (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,latitude NUMERIC(9,6),longitude NUMERIC(9,6),description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(latitude BETWEEN -90 AND 90),CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS environmental_variables (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('air','water','weather')),unit TEXT NOT NULL,min_value NUMERIC,max_value NUMERIC,reference_value NUMERIC,reference_context TEXT,CHECK(min_value IS NULL OR max_value IS NULL OR min_value<=max_value));
CREATE TABLE IF NOT EXISTS measurements (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,site_id BIGINT NOT NULL REFERENCES monitoring_sites(id),variable_id BIGINT NOT NULL REFERENCES environmental_variables(id),user_id BIGINT NOT NULL REFERENCES users(id),value NUMERIC(18,5) NOT NULL,measured_at TIMESTAMPTZ NOT NULL,source_type TEXT NOT NULL DEFAULT 'manual' CHECK(source_type IN ('manual','import','sensor','demo')),quality_status TEXT NOT NULL DEFAULT 'valid' CHECK(quality_status IN ('valid','suspect','rejected')),notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS prediction_runs (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),site_id BIGINT NOT NULL REFERENCES monitoring_sites(id),variable_id BIGINT NOT NULL REFERENCES environmental_variables(id),model_name TEXT NOT NULL,model_version TEXT NOT NULL,metrics JSONB NOT NULL,training_rows INTEGER NOT NULL,testing_rows INTEGER NOT NULL,executed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS predictions (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,run_id BIGINT NOT NULL REFERENCES prediction_runs(id) ON DELETE CASCADE,site_id BIGINT NOT NULL REFERENCES monitoring_sites(id),variable_id BIGINT NOT NULL REFERENCES environmental_variables(id),predicted_value NUMERIC(18,5) NOT NULL,target_date TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT,entity_id BIGINT,details JSONB,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_tokens (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_measurements_site_variable_date ON measurements(site_id,variable_id,measured_at DESC);
CREATE INDEX IF NOT EXISTS ix_measurements_user_date ON measurements(user_id,measured_at DESC);
CREATE INDEX IF NOT EXISTS ix_prediction_runs_site_variable ON prediction_runs(site_id,variable_id,executed_at DESC);
CREATE INDEX IF NOT EXISTS ix_audit_logs_time ON audit_logs(occurred_at DESC);
COMMIT;
